        url = f"{_WATSONX_URL}/ml/v1/text/generation?version=2023-05-29"
        payload = {
            "model_id": _WATSONX_MODEL,
            "input": prompt,
            "parameters": {
                "decoding_method": "greedy",
                "max_new_tokens": 512,
                "temperature": 0.2,
                "stop_sequences": ["</s>"],
            },
            "project_id": _WATSONX_PROJECT_ID,
        }
        resp = _requests.post(
            url,
            json=payload,
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
            timeout=60,
