def _call_watson_discovery_ask(question: str) -> str:
    """Query Watson Discovery for passages relevant to the question."""
    if not _WATSON_DISCO_URL or not _WATSON_DISCO_APIKEY or not _WATSON_DISCO_PROJECT_ID:
        return ""
